INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(14746, 'deDE', 'Der Nordpassturm braucht unsere Hilfe! Lasst uns noch einmal ruhmreich voranstürmen!', '', 31882),
(14745, 'deDE', 'Bitte wirkt einen Stärkungszauber mit hoher Priorität auf alle in der Nähe befindlichen Ziele.', 'Bitte wirkt einen Stärkungszauber mit hoher Priorität auf alle in der Nähe befindlichen Ziele.', 31882),
(14744, 'deDE', 'Bitte wirkt einen Schwächungszauber mit hoher Priorität auf alle in der Nähe befindlichen Ziele.', 'Bitte wirkt einen Schwächungszauber mit hoher Priorität auf alle in der Nähe befindlichen Ziele.', 31882),
(14693, 'deDE', 'Ah, Ich kann es spüren - dies ist Euer Tag! Ich glaube, ich kann Euch jetzt sicher nach Stratholme transportieren, wenn Ihr meinem Kollegen dort bereits besucht habt. Tretet in den Kreis und habt etwas Geduld...', '', 31882),
(14692, 'deDE', 'Es tut gut, die Mauern von Stormwind so stark und sicher zu sehen.$b$bWenn Ihr nach Stratholme wollt, kann ich Euch im Moment nicht helfen. Um die Türme nahe der brennenden Stadt wird noch gekämpft, deshalb reichen meine Kräfte nicht aus. Kommt wieder, wenn Ihr dort siegreich seid.', '', 31882),
(14621, 'deDE', 'Ah, Ich kann es spüren - dies ist Euer Tag! Ich glaube, ich kann Euch jetzt sicher nach Stratholme transportieren, wenn Ihr meinem Kollegen dort bereits besucht habt. Tretet in den Kreis und habt etwas Geduld...', '', 31882),
(14620, 'deDE', 'Unangenehmer Ort, dieses \"Undercity\". Ganz und gar nicht wie das alte Lordaeron. Wie ich es vermisse...$b$bWenn Ihr nach Stratholme wollt, kann ich Euch im Moment nicht helfen. Um die Türme nahe der brennenden Stadt wird noch gekämpft, deshalb reichen meine Kräfte nicht aus. Kommt wieder, wenn Ihr dort siegreich seid.', '', 31882),
(14390, 'deDE', 'Seid gegrüßt, Held. Man wird noch jahrelang über Eure ruhmreichen Taten sprechen. Vielleicht wird eines Tages auch eine Statue von Euch inmitten der Helden von Stormwind stehen.', '', 31882),
(14389, 'deDE', 'Man hat Bescheid gegeben. Er sollte in Kürze hier sein.', '', 31882),
(14388, 'deDE', 'Lasst Marshal Windsor wissen, dass ich bereit bin.', 'Lasst Marshal Windsor wissen, dass ich bereit bin.', 31882),
(14387, 'deDE', 'Ihr habt es geschafft! Außerordentlich! Marshal Windsor hat Euch bereits erwartet. Möchtet Ihr, dass ich ihm jetzt Bescheid sage?', '', 31882),
(14386, 'deDE', 'Marshal Windsor hat Euch bereits erwartet, $N. Unglücklicherweise ist er gerade unpässlich. Er sollte jeden Moment wieder da sein.', '', 31882),
(14385, 'deDE', 'Seid gegrüßt, Bürger. Bitte geht weiter, wenn ich Euch nicht behilflich sein kann.', '', 31882),
(14364, 'deDE', '', 'Die Geister dieses Orts sind Euch gegenüber feindlich gesinnt, $R. Vielleicht werde ich Euch helfen können, wenn Ihr diesen Turm im richtigen Leben erobert.', 31882),
(14018, 'deDE', 'Seid draußen in der Wüste vorsichtig, $C.', '', 31882),
(13995, 'deDE', 'Ich kann in Euren Augen sehen, dass Euch die Tragödie von Stratholme nicht fremd ist. Solltet Ihr dem elenden Dasein dieser armen Seelen, die darin gefangen sind, ein Ende bereiten wollen, so tretet in den Kreis. Er wird Euch direkt zu den Toren der Stadt bringen.', 'Ich kann in Euren Augen sehen, dass Euch die Tragödie von Stratholme nicht fremd ist. Solltet Ihr dem elenden Dasein dieser armen Seelen, die darin gefangen sind, ein Ende bereiten wollen, so tretet in den Kreis. Er wird Euch direkt zu den Toren der Stadt bringen.', 31882),
(13994, 'deDE', 'Es tut mir wirklich Leid, $C, aber da Euer Geist noch nie das Grauen erlebt hat, das innerhalb der brennenden Trümmer von Stratholme liegt, kann unsere Magie Euch nicht zur Stadt bringen.', 'Es tut mir wirklich Leid, $C, aber da Euer Geist noch nie das Grauen erlebt hat, das innerhalb der brennenden Trümmer von Stratholme liegt, kann unsere Magie Euch nicht zur Stadt bringen.', 31882),
(13993, 'deDE', 'Keine Angst; wir sind hier, um Euch zu helfen. Wir fühlen uns für Eure Verteidigung in unserer ehemaligen Heimat zum Dank verpflichtet, deshalb wollen wir Euch als Zeichen unserer Anerkennung helfen, bei Bedarf rasch in die Pestländer zurückzukehren. Mein Landsmann kann Euch alles Weitere erklären; Ihr findet ihn dort, wo die arkanen Energien dieser Stadt am stärksten sind.', 'Keine Angst; wir sind hier, um Euch zu helfen. Wir fühlen uns für Eure Verteidigung in unserer ehemaligen Heimat zum Dank verpflichtet, deshalb wollen wir Euch als Zeichen unserer Anerkennung helfen, bei Bedarf rasch in die Pestländer zurückzukehren. Mein Landsmann kann Euch alles Weitere erklären; Ihr findet ihn dort, wo die arkanen Energien dieser Stadt am stärksten sind.', 31882),
(13765, 'deDE', 'capture point Progress2', '', 31882),
(13764, 'deDE', 'capture point Progress1', '', 31882),
(13763, 'deDE', 'capture point Win2', '', 31882),
(13762, 'deDE', 'capture point Win1', '', 31882),
(13761, 'deDE', 'capture point Contested2', '', 31882),
(13760, 'deDE', 'capture point Contested1', '', 31882),
(13758, 'deDE', '%s atmet tief ein.', '', 31882),
(13675, 'deDE', 'Gebt mir die Reitschildkröte!', 'Gebt mir die Reitschildkröte!', 31882),
(13674, 'deDE', 'Gebt mir das lila Ogerkostüm!', 'Gebt mir das lila Ogerkostüm!', 31882),
(13673, 'deDE', 'Gebt mir das dauerhafte lila Feuerwerk!', 'Gebt mir das dauerhafte lila Feuerwerk!', 31882),
(13672, 'deDE', 'Gebt mir das Hippogryphenjunge!', 'Gebt mir das Hippogryphenjunge!', 31882),
(13671, 'deDE', 'Gebt mir das Tigerbaby!', 'Gebt mir das Tigerbaby!', 31882),
(13670, 'deDE', 'Gebt mir Wappenrock #3!', 'Gebt mir Wappenrock #3!', 31882),
(13669, 'deDE', 'Gebt mir Wappenrock #2!', 'Gebt mir Wappenrock #2!', 31882),
(13657, 'deDE', 'Gebt mir Wappenrock #1!', 'Gebt mir Wappenrock #1!', 31882),
(13656, 'deDE', 'Upperdeck Promotion - Landro Default', '', 31882),
(13655, 'deDE', 'Was für Aktionen bietet Ihr an?', 'Was für Aktionen bietet Ihr an?', 31882),
(13654, 'deDE', 'Upperdeck Promotion - Landro Default', '', 31882),
(13638, 'deDE', '|cff33ccffAlle vier Türme werden jetzt von der Allianz kontrolliert!|r', '', 31882),
(13637, 'deDE', '|cffff0000Alle vier Türme werden jetzt von der Horde kontrolliert!|r', '', 31882),
(13636, 'deDE', '|cffffff00Der Ostwallturm wurde von der Horde besetzt!|r', '', 31882),
(13635, 'deDE', '|cffffff00Der Nordpassturm wurde von der Horde besetzt!|r', '', 31882),
(13634, 'deDE', '|cffffff00Der Pestwaldturm wurde von der Horde besetzt!|r', '', 31882),
(13633, 'deDE', '|cffffff00Der Turm der Kronenwache wurde von der Horde besetzt!|r', '', 31882),
(13632, 'deDE', '|cffffff00Der Turm der Kronenwache wurde von der Allianz besetzt!|r', '', 31882),
(13631, 'deDE', '|cffffff00Der Ostwallturm wurde von der Allianz besetzt!|r', '', 31882),
(13630, 'deDE', '|cffffff00Der Nordpassturm wurde von der Allianz besetzt!|r', '', 31882),
(13629, 'deDE', '|cffffff00Der Pestwaldturm wurde von der Allianz besetzt!|r', '', 31882),
(13584, 'deDE', 'In dieser Gestalt könnt Ihr kein Reittier benutzen.', 'In dieser Gestalt könnt Ihr kein Reittier benutzen.', 31882),
(13564, 'deDE', 'Bringt mich zum Turm der Kronenwache.', 'Bringt mich zum Turm der Kronenwache.', 31882),
(13563, 'deDE', 'Bringt mich zum Ostwallturm.', 'Bringt mich zum Ostwallturm.', 31882),
(13562, 'deDE', 'Bringt mich zum Nordpassturm.', 'Bringt mich zum Nordpassturm.', 31882),
(13561, 'deDE', 'Keine Sorge... meine Greifen sind vielleicht nicht mehr so sattelfest, aber sie werden Euch noch immer getreu an Euer Ziel bringen. Also... zu welchem Turm möchtet Ihr?', 'Keine Sorge... meine Greifen sind vielleicht nicht mehr so sattelfest, aber sie werden Euch noch immer getreu an Euer Ziel bringen. Also... zu welchem Turm möchtet Ihr?', 31882),
(13492, 'deDE', 'Eure lächerlichen Zauber sind keine Herausforderung für die Geißel!', '', 31882),
(13491, 'deDE', 'Transportiert mich zum geschmolzenen Kern, Lothos.', 'Transportiert mich zum geschmolzenen Kern, Lothos.', 31882),
(13481, 'deDE', 'Wir haben fast genug Silithyst! Nicht nachlassen!', '', 31882),
(13480, 'deDE', 'Wir haben die Hälfte unseres benötigten Silithyst! Wir können es schaffen!', '', 31882),
(13479, 'deDE', 'Wir haben ein Viertel des benötigten Silithyst! Weiter so!', '', 31882),
(13478, 'deDE', '', 'Wir haben fast genug Silithyst! Für die Horde!', 31882),
(13477, 'deDE', '', 'Wir haben die Hälfte unseres benötigten Silithyst! Nicht nachlassen!', 31882),
(13476, 'deDE', '', 'Wir haben ein Viertel des benötigten Silithyst! Weiter so!', 31882),
(13470, 'deDE', 'Es ist gelungen! Sieg für die Allianz!', '', 31882),
(13469, 'deDE', '', 'Sieg für die Horde!', 31882),
(13443, 'deDE', 'lässt einen Schwarm los!', '', 31882),
(13434, 'deDE', 'Etwas rührt sich beim Südwindposten! Es... es ist eine dieser Sandwurmkreaturen! Gebt Acht!', '', 31882),
(13433, 'deDE', 'Seid auf der Hut! Es gibt Berichte über einen gigantischen Wurm in der Nähe des Zoraschwarmbaus!', '', 31882),
(13432, 'deDE', 'Seht, da! Beim Bau des Regalschwarms! Ist das... ein Sandwurm?!', '', 31882),
(13431, 'deDE', 'Eine riesige, wurmgleiche Kreatur ist gerade eben aus dem Boden nahe des Ashischwarmbaus hervorgebrochen!', '', 31882),
(13406, 'deDE', '%s nimmt die Energien des Segens der Weisheit in sich auf und wirft sie als Antimagieimpuls zurück.', '', 31882),
(13405, 'deDE', '%s nimmt die Energien des Totems in sich auf und wirft sie als Antimagieimpuls zurück.', '', 31882),
(13254, 'deDE', 'Seid gegrüßt! Ihr kommt mir irgendwie bekannt vor... Kennen wir uns von irgendwoher?$B$BNun, wenn wir uns schon einmal getroffen haben..., dann habt Ihr ja sicherlich einen geheimen Code erhalten. Sagt mir den Code und ich werde Euch ein Geschenk geben!', 'Seid gegrüßt! Ihr kommt mir irgendwie bekannt vor... Kennen wir uns von irgendwoher?$B$BNun, wenn wir uns schon einmal getroffen haben..., dann habt Ihr ja sicherlich einen geheimen Code erhalten. Sagt mir den Code und ich werde Euch ein Geschenk geben!', 31882),
(13253, 'deDE', 'Ich würde gerne den geheimen Code eingeben, um meinen Zerglingbegleiter zu erhalten.', 'Ich würde gerne den geheimen Code eingeben, um meinen Zerglingbegleiter zu erhalten.', 31882),
(13178, 'deDE', 'Dieser andauernde, störende Widerstand ist sinnlos, ihr Maden! Am Ende wartet nur der Tod auf euch!', '', 31882),
(13177, 'deDE', 'Glaubt ihr ernsthaft daran, gegen die Legionen von Kel\'Thuzad bestehen zu können? Nicht die Armeen der Lebenden, noch irgendeine Macht über die ihr möglicherweise verfügt, kann uns aufhalten!', '', 31882),
(13176, 'deDE', 'Die Bemühungen der Lebenden haben uns noch nie beeindruckt. Die Zahl eurer Truppen ist beschränkt und schwindet mit jeder weiteren Schlacht. Ihr werdet nicht mehr lange genug Leben, um das Ende dieses Konflikts zu erleben!', '', 31882),
(13175, 'deDE', 'Ihr Narren! Kämpft nur weiter, wenn es das ist, was ihr wollt! Mit jeder Schlacht fallen mehr von euch und die Reihen der Untoten füllen sich weiter.', '', 31882),
(13174, 'deDE', 'Glaubt ihr tatsächlich, ihr könntet den Meister mit euren kleinen Spielchen beeindrucken? Niemals könnt ihr uns besiegen!', '', 31882),
(13173, 'deDE', 'Glaubt ihr tatsächlich, Fortschritte zu machen? Niemals werdet ihr die Geißel besiegen! Diese vielen kleinen Siege sind nichts weiter, als ein Komplott, um Euch in Sicherheit zu wiegen!', '', 31882),
(13172, 'deDE', 'Ihr habt also ein paar schäbige Landstriche zurückerobert. Lächerlich! Schon in Kürze, werden sie wieder unser sein!', '', 31882),
(13170, 'deDE', 'Auch wenn ihr euch auf dem Schlachtfeld bewährt... werdet ihr niemals den Sieg gegen die Geißel davontragen!', '', 31882),
(13169, 'deDE', 'Glaubt ihr wirklich, eure Bemühungen würden Früchte tragen? Hah! Die Anzahl unserer Kämpfer ist grenzenlos!', '', 31882),
(13165, 'deDE', 'Ihr glaubt vielleicht gewonnen zu haben, Würmer, doch gegen die Macht der Geißel kann es keinen Sieg der Lebenden geben! Das war nicht das Letzte, was ihr von uns gehört habt!', '', 31882),
(13164, 'deDE', 'Ihr wagt es unsere Bemühungen hier zu unterbrechen?! Der Meister wird darüber nicht sehr erfreut sein! Nutzt diese Verschnaufpause und bereitet euch auf das Kommende vor... Wenn wir zurückkehren, wird im Sog unserer Armeen nichts außer Leichen und brennende Erde übrig bleiben.', '', 31882),
(13163, 'deDE', 'Nun, wie es scheint, sind die Lebenden nicht so schwach wie wir angenommen hatten. Gut, nehmt diesen Ort, fürs Erste. Wir werden zurückkehren, zweimal so zahlreich wie heute. An diesem Tage werden eure lächerlichen Armeen dem Erdboden gleichgemacht.', '', 31882),
(13162, 'deDE', 'Der Schatten der Geißel liegt noch immer über diesem Land, ihr Narren! Euer Widerstand ist zwecklos!', '', 31882),
(13161, 'deDE', 'Für Euch gibt es hier keinen Sieg! Dieser Flecken Land wird schon in Kürze von den Armeen der Geißel wie ein Insekt verschluckt werden!', '', 31882),
(13160, 'deDE', 'Genießt Euren kleinen Sieg, solange Ihr es noch könnt, Sterbliche. Diese Niederlage wird unseren entgültigen Triumph über dieses Land nicht verhindern!', '', 31882),
(13159, 'deDE', 'Ihr habt also ein kleines Gebiet zurückerobert. Und wenn schon, es ist nur ein kleiner Rückschlag! Die Geißel wird zurückkehren!', '', 31882),
(13156, 'deDE', 'Hallo, $N. Wie ich sehe, seid Ihr bereits so markiert, als hättet Ihr die Quest, die Euch Zugang zu Naxxramas gewährt, bereits abgeschlossen. Sprecht mit Kommandant Eligor Dawnbringer bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern, um die Quest \"Echo des Krieges\" zu erhalten. Ihr müsst diese Quest zunächst abschließen, um die Folgequest für Euer Rang 3-Rüstungsset starten zu können.$B$BIch kann Euch direkt nach Naxxramas teleportieren. Alternativ könnt Ihr auch das Portal im Westen des Pestwalds verwenden.', '', 31882),
(13154, 'deDE', 'Ich möchte nach Naxxramas teleportiert werden.', 'Ich möchte nach Naxxramas teleportiert werden.', 31882),
(13153, 'deDE', 'I require flagging.', 'I require flagging.', 31882),
(13151, 'deDE', 'Greetings, $N. I am Johnny McWeaksauce. I am used as a tool by developers to carry out specific functions for the purpose of testing. For this test period, I am set to do two specific things:$B$B(1) Flag you as having done the Naxxramas attunement quest so that you are able to accept the next quest, \"Echoes of War\" from Commander Eligor Dawnbringer. You must first complete that quest to be able to access the quests for your Tier 3 armor set.$B$B(2) Teleport you to Naxxramas.$B$BWhat is it that you require?', '', 31882),
(13150, 'deDE', 'Nein!!! Ich verfluche euch, Eindringlinge! Die Armeen des Lichkönigs werden euch jagen und vernichten. Ihr werdet eurem Schicksal nicht entrinnen...', '', 31882),
(13140, 'deDE', 'Sire, der Schüler erbittet für seinen Mangel an Verständnis geschlagen zu werden!', '', 31882),
(13139, 'deDE', 'Der Schüler wird härter arbeiten, Meister!', '', 31882),
(13138, 'deDE', 'Ich bin unwürdig, Meister!', '', 31882),
(13137, 'deDE', 'Der Schüler ist nutzlos, Meister! Der Schüler entschuldigt sich für sein Fehlbetragen!', '', 31882),
(13136, 'deDE', 'Tut endlich etwas, bevor ich anfange meine Übungspuppe durch Euch zu ersetzen und ich meine neuesten Schlagkombinationen an Euch ausprobiere!', '', 31882),
(13135, 'deDE', 'Ist das eine Art Scherz?', '', 31882),
(13134, 'deDE', 'Ihr habt Euch für die falsche Aufgabe entschieden, Initiand. Kel\'thuzad braucht keine Blumenmädchen...', '', 31882),
(13133, 'deDE', 'Meine Großmutter, drüben im Rotkammgebirge schlägt härter zu als Ihr, Anfäger!', '', 31882),
(13132, 'deDE', 'Jämmerlich...', '', 31882),
(13131, 'deDE', 'Ihr verschwendet nicht nur die Zeit meiner Schüler, ihr verschwendet auch meine kostbare Zeit.', '', 31882),
(13130, 'deDE', 'Ist das alles, was Ihr drauf habt?', '', 31882),
(13129, 'deDE', 'Zeigt mir, was ihr könnt, Anfänger!', '', 31882),
(13126, 'deDE', 'Erzitter vor unserer Macht! Flieht! Für die Lebenden wird es keinen Sieg geben!', '', 31882),
(13125, 'deDE', 'Vorwärts, meine Kämpfer! Vorwärts! Lasst euch von Niemanden aufhalten.', '', 31882),
(13124, 'deDE', 'Mit Eurem Tod in der Schlacht, werden wir nur stärker. Das Ende ist absehbar und unausweichlich. Bereitet Euch auf Euer Ende vor!', '', 31882),
(13123, 'deDE', 'Möge diese Dunkelheit Euch an eines erinnern: Der Schatten der Geißel ist allumfassend! Es gibt kein Entkommen!', '', 31882),
(13122, 'deDE', 'Verzweifelt, Sterbliche! Euer Untergang ist nahe!', '', 31882),
(13121, 'deDE', 'Fühlt Ihr es, schwächliche Kreatur? Die Dunkelheit über diesem Land ist nur ein Vorbote dessen, was kommen wird. Schon bald wird alles, was einst Euch gehörte, unser sein! Ihr werdet vor der Macht der Geißel auf die Knie fallen und Euer Ende finden!', '', 31882),
(13120, 'deDE', 'Zeigt mir Euren Eintritt.', 'Zeigt mir Euren Eintritt.', 31882),
(13119, 'deDE', 'Genießt Ihr das Fest, $C? Meine Waren werden Eurem Tag das gewisse Etwas verleihen. Es geht nichts über eine Portion warmes Essen oder etwas zu trinken.$b$bUnd falls Ihr es noch nicht getan habt, schnappt Euch ein oder zwei Freunde und tanzt eine Runde am Sonnenbaum; ich bin sicher, Ihr fühlt Euch danach wie neu geboren!', 'Genießt Ihr das Fest, $C? Meine Waren werden Eurem Tag das gewisse Etwas verleihen. Es geht nichts über eine Portion warmes Essen oder etwas zu trinken.$b$bUnd falls Ihr es noch nicht getan habt, schnappt Euch ein oder zwei Freunde und tanzt eine Runde am Sonnenbaum; ich bin sicher, Ihr fühlt Euch danach wie neu geboren!', 31882),
(13103, 'deDE', 'Hört auf! Kehrt zurück! Kehrt zurück solange ihr noch könnt!', '', 31882),
(13102, 'deDE', 'Vielleicht kommen sie ja noch zur Vernunft... und flüchten so schnell sie können.', '', 31882),
(13101, 'deDE', 'Eindringlinge, macht diesem törichten Unterfangen ein für alle mal ein Ende! Kehrt um!', '', 31882),
(13100, 'deDE', 'Ich habe keine Wahl!', '', 31882),
(13099, 'deDE', 'Vergebt mir.', '', 31882),
(13098, 'deDE', 'Es verläuft... ganz nach Plan.', '', 31882),
(13097, 'deDE', 'Flieht, bevor es zu spät ist!', '', 31882),
(13096, 'deDE', 'Ihr werdet jetzt.... sterben!!', '', 31882),
(13095, 'deDE', 'Neeiiiiiiin!!', '', 31882),
(13094, 'deDE', 'Hilfe! So helft mir doch!', '', 31882),
(13093, 'deDE', 'Aufhören! Bitte aufhöööören!!', '', 31882),
(13092, 'deDE', 'Beeilt euch! Beeilt euch biiiiiitte!!', '', 31882),
(13091, 'deDE', 'Ihr seid zu spät!! Ich... muss.. gehorchen!!', '', 31882),
(13090, 'deDE', 'Jetzt spürt ihr den Schmerz...', '', 31882),
(13089, 'deDE', 'Euch.... dankbar sein!', '', 31882),
(13088, 'deDE', 'Euch... zerquetschen!', '', 31882),
(13087, 'deDE', 'Eure... Knochen... zermalmen...', '', 31882),
(13086, 'deDE', 'Töten...', '', 31882),
(13085, 'deDE', 'Stalagg töten!', '', 31882),
(13084, 'deDE', 'Meister, mich retten!!', '', 31882),
(13083, 'deDE', 'Stalagg zerquetschen!', '', 31882),
(13082, 'deDE', '%s gibt einen Triumphschrei von sich.', '', 31882),
(13081, 'deDE', 'Ihr hättet daheim bleiben sollen!', '', 31882),
(13080, 'deDE', 'Streckt sie nieder... oder habt ihr ein Problem damit?', '', 31882),
(13079, 'deDE', 'Ein ehrenhafter... Tod.', '', 31882),
(13078, 'deDE', 'Die Zeit des Übens ist vorbei! Zeigt mir, was ihr gelernt habt!', '', 31882),
(13077, 'deDE', 'Ihr enttäuscht mich, meine Schüler!', '', 31882),
(13076, 'deDE', 'Lasst keine Gnade walten!', '', 31882),
(13075, 'deDE', 'Befolgt meine Befehle!', '', 31882),
(13074, 'deDE', 'Zeigt mir, was ihr könnt!', '', 31882),
(13073, 'deDE', 'Stellt euch und kämpft!', '', 31882),
(13072, 'deDE', 'Ich fange gerade erst an!', '', 31882),
(13071, 'deDE', 'Nicht mehr spielen?', '', 31882),
(13070, 'deDE', 'Was... sein geschehen...', '', 31882),
(13069, 'deDE', 'Kel\’thuzad macht Flickwerk zu seinem Abgesandten von Krieg!', '', 31882),
(13068, 'deDE', 'Flickwerk spielen möchte!', '', 31882),
(13067, 'deDE', 'Erhebt euch, Soldaten! Erhebt euch und kämpft erneut!', '', 31882),
(13066, 'deDE', 'Sterbt!', '', 31882),
(13065, 'deDE', 'Meine Pflicht ist getan!', '', 31882),
(13064, 'deDE', 'Ich werde dem Meister über den Tod hinaus dienen!', '', 31882),
(13063, 'deDE', 'Sterbt, Eindringling!', '', 31882),
(13062, 'deDE', 'Euer Leben ist verwirkt!', '', 31882),
(13061, 'deDE', 'Ehre unserem Meister!', '', 31882),
(13060, 'deDE', 'Das Leben ist bedeutungslos. Der Tod ist die wahre Prüfung.', '', 31882),
(13059, 'deDE', 'Bewahrt euren Hass. Zügelt euren Zorn. Schon bald könnt ihr eurem Argwohn freien Lauf lassen.', '', 31882),
(13058, 'deDE', 'Genug mit dem Geschwätz. Lasst sie nur kommen. Wir werden ihre Knochen zu Staub zermalmen.', '', 31882),
(13057, 'deDE', 'Beugt euch der Macht des Hochlords!', '', 31882),
(13056, 'deDE', 'Der Wille des Meisters wurde erhört.', '', 31882),
(13055, 'deDE', 'Auch im Tod werdet ihr keine Ruhe finden.', '', 31882),
(13054, 'deDE', 'Ich... bin... wieder frei.... vielleicht ist es noch nicht zu spät - nein! Ich brauche... mehr... Zeit...', '', 31882),
(13053, 'deDE', 'Schweigt!', '', 31882),
(13052, 'deDE', 'Ihr kommt nicht vorbei!', '', 31882),
(13051, 'deDE', 'Ihr sucht den Tod?', '', 31882),
(13050, 'deDE', 'Maden werden sich an eurem faulenden Fleisch laben.', '', 31882),
(13049, 'deDE', 'Euer Ende naht.', '', 31882),
(13048, 'deDE', 'Schon bald wird die Welt erzittern.', '', 31882),
(13047, 'deDE', 'Ich sehe endloses Leiden. Ich sehe Qualen. Ich sehe Zorn. Ich sehe alles...', '', 31882),
(13046, 'deDE', 'Die Völker dieser Welt werden zu Grunde gehen. Es ist nur eine Frage der Zeit.', '', 31882),
(13045, 'deDE', 'Schließt eure Augen. Schlaft.', '', 31882),
(13044, 'deDE', '%s macht seinen letzten Atemzug.', '', 31882),
(13043, 'deDE', 'Ihr seid.... als nächstes dran.', '', 31882),
(13042, 'deDE', 'Ihr entgeht mir nicht...', '', 31882),
(13041, 'deDE', 'Ihr gehört mir...', '', 31882),
(13040, 'deDE', 'Ich werd\' es genießen, diese Waschlappen aus dem Weg zu räumen.', '', 31882),
(13039, 'deDE', 'Ich hab\' genug von Eurem Geflenne! Haltet die Klappe oder ich stopf Euch das Maul!', '', 31882),
(13038, 'deDE', 'Zu den Waffen, Ihr Schmarotzer! Wir haben Gesellschaft!', '', 31882),
(13037, 'deDE', 'Ich mag mein Fleisch besonders knusprig!', '', 31882),
(13036, 'deDE', 'Bringt das nächste Mal mehr Freunde mit!', '', 31882),
(13035, 'deDE', 'Was für eine verdammte Verschwendung!', '', 31882),
(13034, 'deDE', 'Kommt und kämpft, ihr Wichte!', '', 31882),
(13033, 'deDE', 'Doch jetzt gibt es nur noch einen Ausweg  - den einsamen Pfad der Verdammten.', '', 31882),
(13032, 'deDE', 'Tapfer seid ihr in das Reich des Seelenjägers vorgedrungen.', '', 31882),
(13031, 'deDE', 'Voller Leichtsinn habt ihr euch mit Kräften angelegt, die weit über euren Verstand hinausgehen.', '', 31882),
(13030, 'deDE', 'Ihr Narren habt euren eigenen Untergang heraufbeschworen.', '', 31882),
(13029, 'deDE', 'Ihr Narren habt euren eigenen Untergang heraufbeschworen. Voller Leichtsinn habt ihr euch mit Kräften angelegt, die weit über euren Verstand hinausgehen. Tapfer seid ihr in das Reich des Seelenjägers vorgedrungen. Doch jetzt gibt es nur noch einen Ausweg  - den einsamen Pfad der Verdammten.', '', 31882),
(13028, 'deDE', 'Ich habe lange genug gewartet. Stellt euch dem Seelenjäger.', '', 31882),
(13027, 'deDE', 'Tod ist der einzige Ausweg!', '', 31882),
(13026, 'deDE', 'Das ... ist ... mein ... Ende.', '', 31882),
(13025, 'deDE', 'Feugen macht Meister glücklich!', '', 31882),
(13024, 'deDE', 'Kein... Feugen... mehr.', '', 31882),
(13023, 'deDE', 'Verfüttere euch an Meister!', '', 31882),
(13022, 'deDE', '%s lacht höhnisch.', '', 31882),
(13021, 'deDE', 'Die Dunkelheit der Leere erwartet Euch!', '', 31882),
(13020, 'deDE', 'Ich werde das Blut in euren Adern gefrieren lassen!', '', 31882),
(13019, 'deDE', 'Arggggh! Freut Euch nicht zu früh! Euer Sieg ist bedeutungslos, denn ich werde mit Kräften zurückkehren, die weit über eurer Vorstellungskraft hinausgehen.', '', 31882),
(13018, 'deDE', 'Es gibt kein Entkommen!', '', 31882),
(13017, 'deDE', 'Eure Seele gehört jetzt mir!', '', 31882),
(13016, 'deDE', '', 'Ich töte den Ersten! Wer wettet dagegen?', 31882),
(13015, 'deDE', '', 'Ich hoffe, sie bleiben lange genug am Leben... damit ich mich vorstellen kann.', 31882),
(13014, 'deDE', '', 'Zeliek, tötet sie noch nicht. Erst haben wir unseren Spass mit ihnen!', 31882),
(13013, 'deDE', '', 'Euer Leben gehört mir!', 31882),
(13012, 'deDE', '', 'Wer ist der Nächste?', 31882),
(13011, 'deDE', '', 'Touche...', 31882),
(13010, 'deDE', '', 'Verteidigt euch!', 31882),
(13009, 'deDE', 'Kommt näher, Ihr kleinen Leckerbissen. Ich habe mich solange nach Nahrung gesehnt!... Nach Blut, um meinen Durst zu stillen.', '', 31882),
(13008, 'deDE', 'Welchen soll ich nur zuerst verspeisen? Keine leichte Wahl. Sie alle duften so köstlich...', '', 31882),
(13007, 'deDE', 'Wohin gehen? Was tun? So viele Möglichkeiten, und am Ende wartet doch nur der Tod.', '', 31882),
(13006, 'deDE', 'Ich höre das Klopfen kleiner Herzen. Ja...  sie schlagen schneller... bald schon werden sie verstummen.', '', 31882),
(13005, 'deDE', 'Schhh... bald ist alles vorbei.', '', 31882),
(13004, 'deDE', 'Ahh... willkommen in meinem Reich.', '', 31882),
(13003, 'deDE', 'Rennt! Das bringt das Blut in Wallung!', '', 31882),
(13002, 'deDE', 'Es gibt kein Entkommen.', '', 31882),
(13001, 'deDE', '%s eilt Stalagg zu Hilfe!', '', 31882),
(13000, 'deDE', 'Nur einmal kosten...', '', 31882),
(12999, 'deDE', 'Diener, Jünger, Soldaten der eisigen Finsternis! Folgt dem Ruf von Kel\'Thuzad!', '', 31882),
(12998, 'deDE', 'Meister, helft mir!', '', 31882),
(12997, 'deDE', 'Euer Ende ist nah!', '', 31882),
(12996, 'deDE', 'Macht Euren letzten Atemzug!', '', 31882),
(12995, 'deDE', 'Fleht um Gnade!', '', 31882),
(12994, 'deDE', 'Also gut. Erhebt euch, Krieger der eisigen Weiten! Ich befehle euch zu kämpfen, zu töten und für euren Meister zu sterben! Lasst keinen am Leben!', '', 31882),
(12993, 'deDE', 'Kommt nur, ihr Helden... Es ist der Wille des Lichkönigs, dass Ihr vernichtet werdet.', '', 31882),
(12992, 'deDE', 'Ja, Meister!', '', 31882),
(12991, 'deDE', 'Es scheint bisher keine  Komplikationen... Was, was ist das?', '', 31882),
(12990, 'deDE', 'Unsere Vorbereitungen verlaufen wie vorhergesehen, Meister.', '', 31882),
(12989, 'deDE', 'Eure Vorkehrungen waren nutzlos. Ihr wisst, was Ihr zu tun habt!', '', 31882),
(12988, 'deDE', 'Eure Treue ist lobenswert. Schon bald wird jeder dem Lichkönig dienen. Und am Ende auch ihr. Wenn Ihr nicht scheitert.', '', 31882),
(12987, 'deDE', 'Ihr ahnt ja nicht, welche Schrecken noch vor euch liegen. Das Erlebte war erst der Anfang! Das eisige Herz Naxxramas erwartet Euch!', '', 31882),
(12986, 'deDE', 'Eure Spielchen langweilen mich. Fahrt fort, und ich werde eure Seelen der Vergessenheit überantworten.', '', 31882),
(12985, 'deDE', 'Narren! Ihr wähnt euch siegreich? Ihr seid dem Abgrund lediglich einen Schritt näher gekommen!', '', 31882),
(12984, 'deDE', 'Wer wagt es in mein Reich einzudringen? Seid gewarnt: Jeder Eindringling ist verloren!', '', 31882),
(12860, 'deDE', 'Genießt Ihr das Fest, $R?$b$bWährend die Flammenbewahrer sich den Feuern der Gegenwart widmen, bin ich eher ein Historiker, der sich der Vergangenheit dieses Festes verschrieben hat. Natürlich dokumentiere ich auch die diesjährigen Feierlichkeiten. Alles scheint seinen gewohnten Gang zu gehen, meint Ihr nicht?$b$bWisst Ihr, $N, jedem Freudenfeuer wohnt während dieses Fests eine besondere Kraft inne. Wir tragen Sorge für unsere, doch ich bin sicher, dass tief in den Städten unserer Feinde ebenfalls heilige Flammen die Nacht erhellen...', 'Genießt Ihr das Fest, $R?$b$bWährend die Flammenbewahrer sich den Feuern der Gegenwart widmen, bin ich eher ein Historiker, der sich der Vergangenheit dieses Festes verschrieben hat. Natürlich dokumentiere ich auch die diesjährigen Feierlichkeiten. Alles scheint seinen gewohnten Gang zu gehen, meint Ihr nicht?$b$bWisst Ihr, $N, jedem Freudenfeuer wohnt während dieses Fests eine besondere Kraft inne. Wir tragen Sorge für unsere, doch ich bin sicher, dass tief in den Städten unserer Feinde ebenfalls heilige Flammen die Nacht erhellen...', 31882),
(12859, 'deDE', '', 'Flieht, solange ihr noch könnt.', 31882),
(12858, 'deDE', '', 'Kniet nieder, Wurm!', 31882),
(12857, 'deDE', '', 'Ihr könnt euch nicht vor mir verstecken!', 31882),
(12856, 'deDE', '', 'Tötet sie im Namen des Meisters!', 31882),
(12855, 'deDE', '', 'Erbärmliche Kreatur!', 31882),
(12854, 'deDE', '', 'Ihr habt versagt!', 31882),
(12853, 'deDE', '', 'Mein Meister wird mich rächen!!', 31882),
(12852, 'deDE', '', 'Euer altes Leben, eure irdischen Sehnsüchte, sind bedeutungslos... Ihr seid jetzt Akolyten des Meisters und Ihr werden ihm bedingungslos gehorchen! Die höchste Ehre ist es, im Dienste des Meisters zu sterben!', 31882),
(12851, 'deDE', 'Bitte teleportiert mich in in die letzte Kammer.', 'Bitte teleportiert mich in in die letzte Kammer.', 31882),
(12850, 'deDE', '', 'Nachdem Ouro gefallen ist, ist der Weg zur letzten Kammer frei. Ich kann Euch sofort dort hin teleportieren, wenn Ihr wünscht.', 31882),
(12849, 'deDE', 'Bitte teleportiert mich in den Unterschlupf der Imperatoren.', 'Bitte teleportiert mich in den Unterschlupf der Imperatoren.', 31882),
(12848, 'deDE', '', 'Nachdem die Imperatoren gefallen sind, ist die magische Barriere, die Teleportation im Inneren des Tempels verhindert, deutlich geschwächt. Wenn Ihr es wünscht, kann ich Euch direkt in den Unterschlupf der Imperatoren senden.', 31882),
(12831, 'deDE', '', 'iCoke - Description (S.H.E. giftbox)', 31882),
(12830, 'deDE', 'Tell me about the iCoke gift box promotion.', 'Tell me about the iCoke gift box promotion.', 31882),
(12829, 'deDE', '', 'Marketing - iCoke Redemption Greeting (S.H.E. giftbox)', 31882),
(12810, 'deDE', 'Holiday - Scourge Invasion, mystic - how long, Tier 2', '', 31882),
(12809, 'deDE', 'Holiday - Scourge Invasion, mystic - how long, Tier 1', '', 31882),
(12808, 'deDE', 'Holiday - Scourge Invasion, mystic - how long, Tier 0', '', 31882);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(12807, 'deDE', 'Wie lange wird die Invasion noch andauern?', 'Wie lange wird die Invasion noch andauern?', 31882),
(12806, 'deDE', 'Dunkelheit hat sich über unser Land gelegt, $g junger:junge; $N. Werdet Ihr Eure Waffe erheben und Euch dem fliegenden Tod stellen?', '', 31882),
(12804, 'deDE', 'Ich würde gerne nach Thunder Bluff fliegen.', 'Ich würde gerne nach Thunder Bluff fliegen.', 31882),
(12740, 'deDE', '', 'Ah, Ihr seid also der Finder des Briefs. Ich schätze, ich bin Euch für diese Neuigkeiten über meine Familie zu Dank verpflichtet. Bitte, nehmt Euch ruhig von all den Speisen und Getränken.', 31882),
(12739, 'deDE', '', 'Ah, Ihr seid also der Finder des Briefs. Ich schätze, ich bin Euch für diese Neuigkeiten über meine Familie zu Dank verpflichtet. Bitte, nehmt Euch ruhig von all den Speisen und Getränken.', 31882),
