INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(3445, 'deDE', 'Der Windreiterhorst befindet sich ganz oben auf der Totemtreppe in der Stadtmitte.', 'Der Windreiterhorst befindet sich ganz oben auf der Totemtreppe in der Stadtmitte.', 31882),
(3444, 'deDE', 'Die Bank von Thunder Bluff findet Ihr auf der unteren Anhöhe.', 'Die Bank von Thunder Bluff findet Ihr auf der unteren Anhöhe.', 31882),
(3443, 'deDE', 'Der Stier, den Ihr sucht, heißt Krumn. Ihr findet ihn auf der unteren Anhöhe beim Informationszentrum der Stadtverwaltung Thunder Bluff.', 'Der Stier, den Ihr sucht, heißt Krumn. Ihr findet ihn auf der unteren Anhöhe beim Informationszentrum der Stadtverwaltung Thunder Bluff.', 31882),
(3442, 'deDE', '%s singt in einer unbekannten Sprache.', '', 31882),
(3441, 'deDE', '%s lässt die fehlerlose Draenethystsphäre frei vor sich schweben.', '', 31882),
(3430, 'deDE', 'Ein Lehrer für einen Beruf', 'Ein Lehrer für einen Beruf', 31882),
(3429, 'deDE', 'Ein Lehrer für eine Klasse', 'Ein Lehrer für eine Klasse', 31882),
(3428, 'deDE', 'Der Gildenmeister', 'Der Gildenmeister', 31882),
(3427, 'deDE', 'Der Windreitermeister', 'Der Windreitermeister', 31882),
(3426, 'deDE', 'Die Bank', 'Die Bank', 31882),
(3425, 'deDE', 'Ihr sucht doch etwas. Was ist es?', 'Ihr sucht doch etwas. Was ist es?', 31882),
(3424, 'deDE', 'Könnt Ihr mir mit einigen Anweisungen helfen?', 'Könnt Ihr mir mit einigen Anweisungen helfen?', 31882),
(3423, 'deDE', 'Die Geister leiten unsere Schritte auf dem Weg durchs Leben. Wie darf ich Eure leiten?', 'Die Geister leiten unsere Schritte auf dem Weg durchs Leben. Wie darf ich Eure leiten?', 31882),
(3422, 'deDE', 'Wie darf ich Euch mit Weisheit erfüllen?', 'Wie darf ich Euch mit Weisheit erfüllen?', 31882),
(3421, 'deDE', 'Ihr seht mir aus, als benötigtet Ihr Unterstützung. Wie kann ich Euch helfen?', 'Ihr seht mir aus, als benötigtet Ihr Unterstützung. Wie kann ich Euch helfen?', 31882),
(3417, 'deDE', 'Ihr seht mir wahrlich wie ein Schmied aus. Ruß unter den Nägeln, Stahl in den Knochen. Aye, in Euren Adern fließt sehr wohl das Blut eines Schmieds. Was bedeutet, Ihr wollt von mir ein oder zwei Dinge lernen. Nun, $gBursche:Mädel;, schnappt Euch einen Hammer. Und dann lasst uns mal sehen, was ich Euch noch so alles beibringen kann.', '', 31882),
(3416, 'deDE', 'Ich hoffe, Ihr habt nicht den ganzen Weg zur großen Schmiede auf Euch genommen, bloß weil\'s hier so schön warm ist. Sprecht, $gBursche:Mädel;, und sagt mir, was ich für Euch tun kann!', '', 31882),
(3415, 'deDE', 'Ich möchte ein Gildewappen herstellen.', 'Ich möchte ein Gildewappen herstellen.', 31882),
(3414, 'deDE', 'Willkommen bei der Gildenregistrierung von Stormwind. Wie kann ich Euch heute helfen?', 'Willkommen bei der Gildenregistrierung von Stormwind. Wie kann ich Euch heute helfen?', 31882),
(3413, 'deDE', 'Wie gründe ich eine Gilde?', 'Wie gründe ich eine Gilde?', 31882),
(3412, 'deDE', 'Willkommen bei der Gildenregistrierung von Stormwind. Wie kann ich Euch heute helfen?', 'Willkommen bei der Gildenregistrierung von Stormwind. Wie kann ich Euch heute helfen?', 31882),
(3411, 'deDE', 'Sprecht leise und vorsichtig. Ein falsches Wort kann Euch hierzulande den Kopf kosten. Nun denn, was ist Euer Begehr?', 'Sprecht leise und vorsichtig. Ein falsches Wort kann Euch hierzulande den Kopf kosten. Nun denn, was ist Euer Begehr?', 31882),
(3410, 'deDE', 'Sprecht leise und vorsichtig. Ein falsches Wort kann Euch hierzulande den Kopf kosten. Nun denn, was ist Euer Begehr?', 'Sprecht leise und vorsichtig. Ein falsches Wort kann Euch hierzulande den Kopf kosten. Nun denn, was ist Euer Begehr?', 31882),
(3409, 'deDE', 'Ich brauche einen Flug.', 'Ich brauche einen Flug.', 31882),
(3408, 'deDE', 'Diese großen Wildtiere kennen Wege, die man zu Fuß nie und nimmer finden würde. Sie bringen Euch blitzschnell überallhin und zeigen Euch dabei womöglich noch etwas Neues.', 'Diese großen Wildtiere kennen Wege, die man zu Fuß nie und nimmer finden würde. Sie bringen Euch blitzschnell überallhin und zeigen Euch dabei womöglich noch etwas Neues.', 31882),
(3407, 'deDE', 'Wohin des Weges, $gBursche:Mädel;? Wohin Ihr auch wollt, für ein paar Münzen bringen Euch meine Greife in Windeseile hin.', 'Wohin des Weges, $gBursche:Mädel;? Wohin Ihr auch wollt, für ein paar Münzen bringen Euch meine Greife in Windeseile hin.', 31882),
(3406, 'deDE', 'Wir sind die einzigen Lieferanten von gesunden Blumen in ganz Stormwind. Wir haben wunderschöne Blumen für jeden Anlass.', 'Wir sind die einzigen Lieferanten von gesunden Blumen in ganz Stormwind. Wir haben wunderschöne Blumen für jeden Anlass.', 31882),
(3405, 'deDE', 'Willkommen bei der Bank von Stormwind. Wir bieten Bankkonten und Schließfächer für wertvolle Gegenstände. Habt Ihr bereits ein Konto bei uns, $gwerter Herr:gnädige Frau;?', 'Willkommen bei der Bank von Stormwind. Wir bieten Bankkonten und Schließfächer für wertvolle Gegenstände. Habt Ihr bereits ein Konto bei uns, $gwerter Herr:gnädige Frau;?', 31882),
(3404, 'deDE', 'Willkommen im Pfeifenden Schwein! Holt Euch was zu trinken und setzt Euch. Je mehr, desto lustiger!', 'Willkommen im Pfeifenden Schwein! Holt Euch was zu trinken und setzt Euch. Je mehr, desto lustiger!', 31882),
(3403, 'deDE', 'Hört auf meinen Rat und haltet Euch von den Schatten fern.', 'Hört auf meinen Rat und haltet Euch von den Schatten fern.', 31882),
(3402, 'deDE', 'Willkommen im Blauen Eremiten, wo die Magiebegabten Dampf ablassen. Was natürlich nicht wörtlich zu nehmen ist. Womit kann ich Euch dienen, $gwerter Herr:holde Dame;?', 'Willkommen im Blauen Eremiten, wo die Magiebegabten Dampf ablassen. Was natürlich nicht wörtlich zu nehmen ist. Womit kann ich Euch dienen, $gwerter Herr:holde Dame;?', 31882),
(3401, 'deDE', 'Womit kann ich Euch dienen, $gSire:holde Dame;?', 'Womit kann ich Euch dienen, $gSire:holde Dame;?', 31882),
(3400, 'deDE', 'Wer wagt es, Archaedas zu wecken? Wer riskiert den Zorn der Schöpfer?', '', 31882),
(3399, 'deDE', '%s befreit sich aus seinem Steinschlummer!', 'befreit sich aus seinem Steinschlummer!', 31882),
(3398, 'deDE', 'Ich möchte einen Blick in mein Schließfach werfen.', 'Ich möchte einen Blick in mein Schließfach werfen.', 31882),
(3397, 'deDE', 'Hier wurde noch nie etwas gestohlen. Noch nie in der ganzen Geschichte von... der ganzen Geschichte!', 'Hier wurde noch nie etwas gestohlen. Noch nie in der ganzen Geschichte von... der ganzen Geschichte!', 31882),
(3396, 'deDE', 'Wenn Ihr Lasche A in Schlitz B steckt, dann macht\'s natürlich BUMM! Lasst mich Euch mal zeigen, was ich habe. Danach könnt Ihr Lilliam fragen, wie man es zusammensetzt, ohne dass es Euch um die Ohren fliegt.', 'Wenn Ihr Lasche A in Schlitz B steckt, dann macht\'s natürlich BUMM! Lasst mich Euch mal zeigen, was ich habe. Danach könnt Ihr Lilliam fragen, wie man es zusammensetzt, ohne dass es Euch um die Ohren fliegt.', 31882),
(3395, 'deDE', 'Ein Ingenieur! Hey, endlich kann ich mal die neuen Geräte zeigen, die ich gebaut habe!', 'Ein Ingenieur! Hey, endlich kann ich mal die neuen Geräte zeigen, die ich gebaut habe!', 31882),
(3394, 'deDE', 'He da, $gwerter Herr:holde Dame;! An Eurer Stelle würde ich aufpassen, wo ich hintrete. Ich habe hier eine als Maus getarnte Bombe verloren und kann sie nicht mehr finden.', 'He da, $gwerter Herr:holde Dame;! An Eurer Stelle würde ich aufpassen, wo ich hintrete. Ich habe hier eine als Maus getarnte Bombe verloren und kann sie nicht mehr finden.', 31882),
(3393, 'deDE', 'Wir führen eine kleine Auswahl arkaner Handwerkswaren für mystische Handwerker. Sucht Ihr etwas Bestimmtes?', 'Wir führen eine kleine Auswahl arkaner Handwerkswaren für mystische Handwerker. Sucht Ihr etwas Bestimmtes?', 31882),
(3392, 'deDE', 'Viel vom Grundbedarf der Handwerker ist in der Welt zu finden. Von dem, was nicht zu finden ist, biete ich einige Stücke zu einem guten Preis an.', 'Viel vom Grundbedarf der Handwerker ist in der Welt zu finden. Von dem, was nicht zu finden ist, biete ich einige Stücke zu einem guten Preis an.', 31882),
(3391, 'deDE', 'Wir führen eine kleine Auswahl arkaner Handwerkswaren für mystische Handwerker. Sucht Ihr etwas Bestimmtes?', 'Wir führen eine kleine Auswahl arkaner Handwerkswaren für mystische Handwerker. Sucht Ihr etwas Bestimmtes?', 31882),
(3390, 'deDE', 'Lasst Euch von den Menschen auf dem Basar nicht über den Tisch ziehen, $gBursche:Mädel;. Mit der von den Gnomen gebauten Untergrundbahn ist es leichter, als Ihr vielleicht glaubt, Waren von Ironforge hierher zu schaffen. Wenn sie Euch was von Importzöllen erzählen wollen, sagt Ihr einfach, Ihr kauft Eure Sachen bei mir.', 'Lasst Euch von den Menschen auf dem Basar nicht über den Tisch ziehen, $gBursche:Mädel;. Mit der von den Gnomen gebauten Untergrundbahn ist es leichter, als Ihr vielleicht glaubt, Waren von Ironforge hierher zu schaffen. Wenn sie Euch was von Importzöllen erzählen wollen, sagt Ihr einfach, Ihr kauft Eure Sachen bei mir.', 31882),
(3389, 'deDE', 'Möge das Licht Euch den Weg weisen und Euch auf Euren Reisen beschützen. Wenn Ihr Hilfe braucht, stehe ich Euch zur Verfügung.', 'Möge das Licht Euch den Weg weisen und Euch auf Euren Reisen beschützen. Wenn Ihr Hilfe braucht, stehe ich Euch zur Verfügung.', 31882),
(3388, 'deDE', 'Möge das Licht Euch den Weg weisen und Euch auf Euren Reisen beschützen. Wenn Ihr Hilfe braucht, stehe ich Euch zur Verfügung.', 'Möge das Licht Euch den Weg weisen und Euch auf Euren Reisen beschützen. Wenn Ihr Hilfe braucht, stehe ich Euch zur Verfügung.', 31882),
(3387, 'deDE', 'Ich führe nur die beste Ausrüstung, geprüft und echt. Die Preise stehen fest. Wenn Ihr also feilschen wollt, sucht Euch einen Goblin.', 'Ich führe nur die beste Ausrüstung, geprüft und echt. Die Preise stehen fest. Wenn Ihr also feilschen wollt, sucht Euch einen Goblin.', 31882),
(3386, 'deDE', 'Ich führe nur die beste Ausrüstung, geprüft und echt. Die Preise stehen fest. Wenn Ihr also feilschen wollt, sucht Euch einen Goblin.', 'Ich führe nur die beste Ausrüstung, geprüft und echt. Die Preise stehen fest. Wenn Ihr also feilschen wollt, sucht Euch einen Goblin.', 31882),
(3385, 'deDE', 'Ich führe nur die beste Ausrüstung, geprüft und echt. Die Preise stehen fest. Wenn Ihr also feilschen wollt, sucht Euch einen Goblin.', 'Ich führe nur die beste Ausrüstung, geprüft und echt. Die Preise stehen fest. Wenn Ihr also feilschen wollt, sucht Euch einen Goblin.', 31882),
(3384, 'deDE', 'Seht Ihr Euch nur um oder kann ich Euch irgendwie helfen?', 'Seht Ihr Euch nur um oder kann ich Euch irgendwie helfen?', 31882),
(3383, 'deDE', 'Die besten Preise in ganz Stormwind, was Besseres werdet Ihr nicht finden. Womit kann ich Euch denn nun dienen?', 'Die besten Preise in ganz Stormwind, was Besseres werdet Ihr nicht finden. Womit kann ich Euch denn nun dienen?', 31882),
