(1718, 'esES', '¡Ave $N a todos, un $c de valor!', '', 31882),
(1717, 'esES', 'hace crujir los nudillos.', '', 31882),
(1716, 'esES', 'Está bien, jefe. Pero ¿seguro? Sería un desperdicio no aprovechar tanto talento.', '', 31882),
(1715, 'esES', 'Sí, vale, jefe. No hay problema.', '', 31882),
