(12720, 'frFR', 'J\'ai perdu mon anneau des secrets scellés. Pouvez-vous le remplacer ?', 'J\'ai perdu mon anneau des secrets scellés. Pouvez-vous le remplacer ?', 31882),
(12719, 'frFR', 'J\'ai perdu ma chevalière du sentier invisible. Pouvez-vous la remplacer ?', 'J\'ai perdu ma chevalière du sentier invisible. Pouvez-vous la remplacer ?', 31882),
(12718, 'frFR', 'J\'ai perdu mon anneau de vie interminable. Pouvez-vous le remplacer ?', 'J\'ai perdu mon anneau de vie interminable. Pouvez-vous le remplacer ?', 31882),
(12717, 'frFR', 'J\'ai perdu mon drapé de force inflexible. Pouvez-vous le remplacer ?', 'J\'ai perdu mon drapé de force inflexible. Pouvez-vous le remplacer ?', 31882),
(12716, 'frFR', 'J\'ai perdu mon voile des noms inexprimés. Pouvez-vous le remplacer ?', 'J\'ai perdu mon voile des noms inexprimés. Pouvez-vous le remplacer ?', 31882),
(12715, 'frFR', 'J\'ai perdu ma cape de la tempête imminente. Pouvez-vous la remplacer ?', 'J\'ai perdu ma cape de la tempête imminente. Pouvez-vous la remplacer ?', 31882),
(12714, 'frFR', 'J\'ai perdu ma cape des ombres voilées. Pouvez-vous la remplacer ?', 'J\'ai perdu ma cape des ombres voilées. Pouvez-vous la remplacer ?', 31882),
(12713, 'frFR', 'J\'ai perdu mon voile de sagesse infinie. Pouvez-vous le remplacer ?', 'J\'ai perdu mon voile de sagesse infinie. Pouvez-vous le remplacer ?', 31882),
(12712, 'frFR', 'J\'ai perdu ma cape de justice éternelle. Pouvez-vous la remplacer ?', 'J\'ai perdu ma cape de justice éternelle. Pouvez-vous la remplacer ?', 31882),
(12711, 'frFR', 'J\'ai perdu mon drapé des secrets scellés. Pouvez-vous le remplacer ?', 'J\'ai perdu mon drapé des secrets scellés. Pouvez-vous le remplacer ?', 31882),
(12710, 'frFR', 'J\'ai perdu ma cape du sentier invisible. Pouvez-vous la remplacer ?', 'J\'ai perdu ma cape du sentier invisible. Pouvez-vous la remplacer ?', 31882),
(12708, 'frFR', 'J\'ai perdu ma cape de vie interminable. Pouvez-vous la remplacer ?', 'J\'ai perdu ma cape de vie interminable. Pouvez-vous la remplacer ?', 31882),
(12705, 'frFR', 'J\'ai perdu ma faucille de force inflexible. Pouvez-vous la remplacer ?', 'J\'ai perdu ma faucille de force inflexible. Pouvez-vous la remplacer ?', 31882),
(12702, 'frFR', 'J\'ai perdu mon kriss des noms inexprimés. Pouvez-vous le remplacer ?', 'J\'ai perdu mon kriss des noms inexprimés. Pouvez-vous le remplacer ?', 31882),
(12701, 'frFR', 'J\'ai perdu mon marteau de la tempête imminente. Pouvez-vous le remplacer ?', 'J\'ai perdu mon marteau de la tempête imminente. Pouvez-vous le remplacer ?', 31882),
(12699, 'frFR', 'J\'ai perdu ma dague des ombres voilées. Pouvez-vous la remplacer ?', 'J\'ai perdu ma dague des ombres voilées. Pouvez-vous la remplacer ?', 31882),
(12697, 'frFR', 'J\'ai perdu mon marteau de sagesse infinie. Pouvez-vous le remplacer ?', 'J\'ai perdu mon marteau de sagesse infinie. Pouvez-vous le remplacer ?', 31882),
(12696, 'frFR', 'J\'ai perdu ma lame de justice éternelle. Pouvez-vous la remplacer ?', 'J\'ai perdu ma lame de justice éternelle. Pouvez-vous la remplacer ?', 31882),
(12695, 'frFR', 'J\'ai perdu ma lame des secrets scellés. Pouvez-vous la remplacer ?', 'J\'ai perdu ma lame des secrets scellés. Pouvez-vous la remplacer ?', 31882),
(12694, 'frFR', 'J\'ai perdu ma faux du sentier invisible. Pouvez-vous la remplacer ?', 'J\'ai perdu ma faux du sentier invisible. Pouvez-vous la remplacer ?', 31882),
(12693, 'frFR', 'J\'ai perdu ma masse de vie interminable. Pouvez-vous la remplacer ?', 'J\'ai perdu ma masse de vie interminable. Pouvez-vous la remplacer ?', 31882),
(12682, 'frFR', 'Mes couvre-bras de démoniaque zandalar sont introuvables. En auriez-vous une autre paire ?', 'Mes couvre-bras de démoniaque zandalar sont introuvables. En auriez-vous une autre paire ?', 31882),
(12681, 'frFR', 'Al\’tabim, j\’ai perdu mon mantelet de démoniaque zandalar. Pourriez-vous m\’aider ?', 'Al\’tabim, j\’ai perdu mon mantelet de démoniaque zandalar. Pourriez-vous m\’aider ?', 31882),
