(6615, 'esMX', 'Brujo', 'Brujo', 31882),
(6612, 'esMX', '%s se despierta.', '', 31882),
(6608, 'esMX', 'Pícaro', 'Pícaro', 31882),
(6607, 'esMX', 'Hemos oído tus peticiones y estamos de acuerdo... es un noble propósito. Purificaremos tus aguas. Márchate con nuestra bendición, chamán.', '', 31882),
(6606, 'esMX', 'Chamán', 'Chamán', 31882),
(6605, 'esMX', 'Sacerdote', 'Sacerdote', 31882),
