(12682, 'ptBR', 'As minhas Braçadeiras do Demoníaco Zandalar desapareceram. Você pode me fornecer outras?', 'As minhas Braçadeiras do Demoníaco Zandalar desapareceram. Você pode me fornecer outras?', 31882),
(12681, 'ptBR', 'Al\'tabim, eu perdi as minhas Dragonas do Demoníaco Zandalar. Você pode me ajudar?', 'Al\'tabim, eu perdi as minhas Dragonas do Demoníaco Zandalar. Você pode me ajudar?', 31882),
(12680, 'ptBR', 'Eu perdi a minha Veste do Demoníaco Zandalar. Você pode me arranjar outra?', 'Eu perdi a minha Veste do Demoníaco Zandalar. Você pode me arranjar outra?', 31882),
(12679, 'ptBR', 'Eu perdi os meus Bracelete do Ilusionista Zandalar e preciso de outro par.', 'Eu perdi os meus Bracelete do Ilusionista Zandalar e preciso de outro par.', 31882),
(12678, 'ptBR', 'Al\'tabim, acho que eu perdi as minhas Dragonas do Ilusionista Zandalar. Você poderia repô-las para mim?', 'Al\'tabim, acho que eu perdi as minhas Dragonas do Ilusionista Zandalar. Você poderia repô-las para mim?', 31882),
(12677, 'ptBR', 'Eu perdi a minha Veste do Ilusionista Zandalar e preciso de outra, Al\'tabim.', 'Eu perdi a minha Veste do Ilusionista Zandalar e preciso de outra, Al\'tabim.', 31882),
(12676, 'ptBR', 'Al\'tabim, as minhas Braçadeiras do Confessor Zandalar sumiram. Você poderia repô-las?', 'Al\'tabim, as minhas Braçadeiras do Confessor Zandalar sumiram. Você poderia repô-las?', 31882),
