(6897, 'ptBR', 'Fordring nunca verá o filho.', 'Fordring nunca verá o filho.', 31882),
(6896, 'ptBR', '', 'Seu sangue jorra pelo bem da humanidade, infiel!', 31882),
(6895, 'ptBR', 'TEST - death after attack $n', '', 31882),
